export class SessionBroker {
  constructor() {
    this.sessions = new Map()
  }

  register(session) {
    this.sessions.set(session.id, session)
  }

  async send(targetId, command) {
    const target = this.sessions.get(targetId)
    if (!target) throw new Error(`unknown session: ${targetId}`)
    return target.provider.send(command)
  }
}

export class VoiceController {
  constructor(broker, permissions) {
    this.broker = broker
    this.permissions = permissions
  }

  async submit(source, target, transcript) {
    if (!this.permissions.canControl(source, target)) {
      throw new Error('permission denied')
    }
    return this.broker.send(target, { type: 'user-turn', text: transcript })
  }
}

export class PermissionRouter {
  constructor(policy) {
    this.policy = policy
  }

  async authorize({ actor, action, target }) {
    const decision = await this.policy.evaluate({
      actor,
      action,
      target,
      provider: target.provider.name,
    })
    return decision.allowed
  }
}

export class VoiceController {
  constructor(broker, permissionRouter) {
    this.broker = broker
    this.permissionRouter = permissionRouter
  }

  async submit(source, target, transcript) {
    const allowed = await this.permissionRouter.authorize({
      actor: source,
      action: 'session.control',
      target,
    })
    if (!allowed) throw new Error('permission denied')
    return this.broker.send(target.id, { type: 'user-turn', text: transcript })
  }
}

import test from 'node:test'
import assert from 'node:assert/strict'
import { PermissionRouter } from '../src/permissions/router.js'

test('passes provider context to the shared policy', async () => {
  let input
  const router = new PermissionRouter({ evaluate: async value => { input = value; return { allowed: true } } })
  const allowed = await router.authorize({ actor: { id: 'a' }, action: 'session.control', target: { id: 'b', provider: { name: 'codex' } } })
  assert.equal(allowed, true)
  assert.equal(input.provider, 'codex')
})
